import{_ as e,o as a,c as i,a2 as s}from"./chunks/framework.dWYrTn1b.js";const u=JSON.parse('{"title":"Installation","description":"Install the RobotDSL compiler, get a component library, and set up an environment to run the output.","frontmatter":{"title":"Installation","description":"Install the RobotDSL compiler, get a component library, and set up an environment to run the output."},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),o={name:"guide/installation.md"};function n(r,t,l,h,d,p){return a(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>The compiler is plain Python. It needs no ROS, simulator or Docker; those are only for running what it writes.</p><h2 id="the-compiler" tabindex="-1">The compiler <a class="header-anchor" href="#the-compiler" aria-label="Permalink to &quot;The compiler&quot;">​</a></h2><p>RobotDSL needs Python 3.12 or later. From a checkout of the repository:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>This installs the <code>mobiledsl</code> command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mobiledsl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mobiledsl 0.1.0</span></span></code></pre></div><p>To work on the compiler itself, install the development tools too; <a href="./../development/onboarding.html">Developer onboarding</a> covers the test suite.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.[dev]&#39;</span></span></code></pre></div><h2 id="a-component-library" tabindex="-1">A component library <a class="header-anchor" href="#a-component-library" aria-label="Permalink to &quot;A component library&quot;">​</a></h2><p>A program assembles its robot from parts in a component library, a directory the compiler reads with <code>--library</code>. Two are at hand:</p><table tabindex="0"><thead><tr><th>Library</th><th>Holds</th></tr></thead><tbody><tr><td><code>examples/library</code> in this repository</td><td>The parts of the example robots used in this guide and in the tests, with placeholder meshes</td></tr><tr><td>The <code>format-1</code> branch of the component library repository</td><td>The real catalog, with CAD meshes</td></tr></tbody></table><p>There is no default library and no install step: a library is used by naming its directory. <a href="./basics/libraries.html">Component libraries</a> explains what is inside one.</p><h2 id="an-environment-to-run-the-output" tabindex="-1">An environment to run the output <a class="header-anchor" href="#an-environment-to-run-the-output" aria-label="Permalink to &quot;An environment to run the output&quot;">​</a></h2><p>The output of <code>--target ros-gz-nav2</code> runs on ROS 2 Jazzy with Gazebo Harmonic, <code>ros2_control</code> and Nav2. The output of <code>--target ros-mujoco-nav2</code> runs on ROS 2 Jazzy with MuJoCo 3.3, <code>ros2_control</code>, Nav2 and <code>topic_based_ros2_control</code>. Nothing in the output is built or installed.</p><p>If you do not have such an environment, use the images the test suite runs in:</p><table tabindex="0"><thead><tr><th>Image</th><th>Target</th></tr></thead><tbody><tr><td><code>robotdsl/ros-gz-nav2:jazzy-harmonic</code></td><td><code>ros-gz-nav2</code></td></tr><tr><td><code>robotdsl/ros-mujoco-nav2:jazzy</code></td><td><code>ros-mujoco-nav2</code></td></tr></tbody></table><p><code>docker/README.md</code> in the repository says how each is built.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./getting-started.html">Getting started</a> writes, checks, compiles and runs a first program.</p>',21)])])}const m=e(o,[["render",n]]);export{u as __pageData,m as default};
